// Minimum-span layering against a linear-program solver at scale: a DAG of 5 × 10⁴ vertices with
// short random arcs, whose least total span scipy's HiGHS found once, precomputed by swiftgen.py
// (lp_span), under a bound on its own time. The 400 small DAGs are in
// SugiyamaLayeringLinearProgramTests.swift. Generated by swiftgen.py; see README.md.

import GraphDrawing
import GraphProtocols
import Multigraphs
import Testing

@Suite("Sugiyama layering against a linear program at scale")
struct SugiyamaLayeringLinearProgramScaleTests {
    // Release: 0.23 s; Gansner's pivots, searching a side of a cut each, took 1.5 s. The
    // bound is for a debug build. Crossing reduction is off: the layering is under test.
    @Test("At 5 × 10⁴ vertices with short random arcs: the LP optimum (HiGHS: 172087)", .timeLimit(.minutes(1)))
    func largeSpanMatchesTheLinearProgram() async {
        await Task {
            let n = 50000
            var x: UInt64 = 1
            var arcs: [DirectedEdge<Int>] = []
            for v in 0 ..< n {
                for _ in 0 ..< 2 {
                    x = x &* 6_364_136_223_846_793_005 &+ 1_442_695_040_888_963_407
                    let w = v + 1 + Int((x >> 33) % 20)
                    if w < n { arcs.append(DirectedEdge(from: v, to: w)) }
                }
            }
            let graph = DirectedPseudograph<Int>(vertices: 0 ..< n, edges: arcs)
            let clock = ContinuousClock()
            let start = clock.now
            let layered = graph.sugiyamaLayout(maxIterations: 0)
            let elapsed = clock.now - start
            #expect(elapsed < .seconds(30), "\(elapsed)")
            let spans = arcs.map { layered.layer(of: $0.target) - layered.layer(of: $0.source) }
            #expect(spans.allSatisfy { $0 >= 1 })
            #expect(spans.reduce(0, +) == 172087)
        }.value
    }
}
